    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: light;
        --background: #f6f8fb;
        --card: #ffffff;
        --text: #172033;
        --muted: #667085;
        --border: #d7deea;
        --primary: #315cf6;
        --primary-dark: #2446c7;
        --focus: #8ea4ff;
        --shadow: 0 24px 70px rgba(23, 32, 51, 0.14);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(49, 92, 246, 0.18), transparent 32rem),
          linear-gradient(135deg, #fbfcff 0%, var(--background) 100%);
      }

      .page-shell {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 2rem;
      }

      .support-card {
        width: min(100%, 48rem);
        padding: clamp(1.5rem, 4vw, 3rem);
        background: rgba(255, 255, 255, 0.92);
        border: 1px solid rgba(215, 222, 234, 0.9);
        border-radius: 1.75rem;
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        margin: 0 0 1rem;
        padding: 0.35rem 0.75rem;
        color: #2144bf;
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.02em;
        background: #eef3ff;
        border-radius: 999px;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.4rem);
        line-height: 1.05;
        letter-spacing: -0.045em;
      }

      .intro {
        max-width: 39rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.0625rem;
        line-height: 1.65;
      }

      .contact-form {
        display: grid;
        gap: 1.125rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        font-size: 0.95rem;
        font-weight: 700;
      }

      .optional {
        color: var(--muted);
        font-weight: 600;
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        padding: 0.85rem 1rem;
        color: var(--text);
        font: inherit;
        background: #ffffff;
        border: 1px solid var(--border);
        border-radius: 0.95rem;
        outline: none;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      input::placeholder {
        color: #98a2b3;
      }

      input:focus {
        border-color: var(--primary);
        box-shadow: 0 0 0 4px rgba(142, 164, 255, 0.35);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.9rem;
        line-height: 1.45;
      }

      .submit-button {
        justify-self: start;
        min-height: 3.25rem;
        margin-top: 0.5rem;
        padding: 0.9rem 1.35rem;
        color: #ffffff;
        font: inherit;
        font-weight: 800;
        background: linear-gradient(135deg, var(--primary), #6d5dfc);
        border: 0;
        border-radius: 999px;
        box-shadow: 0 14px 28px rgba(49, 92, 246, 0.26);
        cursor: pointer;
        transition:
          background 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      .submit-button:hover {
        background: linear-gradient(135deg, var(--primary-dark), #5b4fe0);
        transform: translateY(-1px);
      }

      .submit-button:focus-visible {
        outline: 4px solid var(--focus);
        outline-offset: 3px;
      }

      @media (max-width: 42rem) {
        .page-shell {
          padding: 1rem;
        }

        .support-card {
          border-radius: 1.25rem;
        }

        .submit-button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const html = String.raw;

      function FormField({
        id,
        label,
        type = "text",
        name,
        autocomplete,
        placeholder,
        required = false,
        helperText = "",
        inputmode = "",
      }) {
        const helperId = helperText ? `${id}-helper` : "";
        const requiredText = required ? "" : ' <span class="optional">(optional)</span>';
        const requiredAttribute = required ? " required" : "";
        const autocompleteAttribute = autocomplete ? ` autocomplete="${autocomplete}"` : "";
        const inputmodeAttribute = inputmode ? ` inputmode="${inputmode}"` : "";
        const describedByAttribute = helperId ? ` aria-describedby="${helperId}"` : "";
        const helperMarkup = helperText
          ? `<p class="helper-text" id="${helperId}">${helperText}</p>`
          : "";

        return html`
          <div class="form-field">
            <label for="${id}">${label}${requiredText}</label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              placeholder="${placeholder}"
              ${requiredAttribute}${autocompleteAttribute}${inputmodeAttribute}${describedByAttribute}
            >
            ${helperMarkup}
          </div>
        `;
      }

      function ContactForm() {
        return html`
          <form class="contact-form" action="#" method="post" novalidate>
            ${FormField({
              id: "full-name",
              label: "Full name",
              name: "fullName",
              autocomplete: "name",
              placeholder: "Jane Doe",
              required: true,
            })}
            ${FormField({
              id: "email-address",
              label: "Email address",
              type: "email",
              name: "email",
              autocomplete: "email",
              placeholder: "jane@example.com",
              required: true,
            })}
            ${FormField({
              id: "phone-number",
              label: "Phone number",
              type: "tel",
              name: "phone",
              autocomplete: "tel",
              inputmode: "tel",
              placeholder: "+1 555 123 4567",
              helperText: "Use an international format, such as +1 555 123 4567.",
            })}
            <button class="submit-button" type="submit">Contact support</button>
          </form>
        `;
      }

      function App() {
        return html`
          <main class="page-shell">
            <section class="support-card" aria-labelledby="support-title">
              <p class="eyebrow">Support request</p>
              <h1 id="support-title">How can we help?</h1>
              <p class="intro">
                Send our support team your contact details and we will follow up with
                the next best step.
              </p>
              ${ContactForm()}
            </section>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = App();
    </script>
  </body>
</html>
